import './header.css';
import React, { useEffect, useState } from 'react';
const navigation = [
    ['home', 'Home', 'uil-estate'],
    ['about', 'About', 'uil-user'],
    ['skills', 'Skills', 'uil-file-alt'],
    ['internships', 'Experience', 'uil-briefcase-alt'],
    ['projects', 'Projects', 'uil-folder-open'],
    ['education', 'Education', 'uil-graduation-cap'],
    ['contact', 'Contact', 'uil-message'],
];

export function Header(){
    const [showMenu, setShowMenu] = useState(false);
    const [activeNav, setActiveNav] = useState('home');
    const [scrolled, setScrolled] = useState(false);
    useEffect(() => {
        const sections = navigation.map(([id]) => document.getElementById(id)).filter(Boolean);
        const observer = new IntersectionObserver((entries) => {
            const visibleSection = entries.find((entry) => entry.isIntersecting);
            if (visibleSection) setActiveNav(visibleSection.target.id);
        }, { rootMargin: '-30% 0px -60% 0px' });
        sections.forEach((section) => observer.observe(section));
        return () => observer.disconnect();
    }, []);

    useEffect(() => {
        const updateHeader = () => setScrolled(window.scrollY > 16);
        window.addEventListener('scroll', updateHeader, { passive: true });
        updateHeader();
        return () => window.removeEventListener('scroll', updateHeader);
    }, []);

    const closeMenu = () => {
        setShowMenu(false);
    };

    return(
        <header className={`header${scrolled ? ' scroll-header' : ''}`}>
            <nav className="nav container" aria-label="Main navigation">
                <a href="#home" className="nav__logo" onClick={closeMenu}>
                    <span className="nav__logo-mark">N</span>
                    <span>Nikitha<span className="nav__logo-dot">.</span></span>
                </a>
                <div id="site-navigation" className={`nav__menu${showMenu ? ' show-menu' : ''}`}>
                    <ul className="nav__list">
                        {navigation.map(([id, label, icon]) => (
                            <li key={id}>
                                <a href={`#${id}`} onClick={closeMenu} className={`nav__link${activeNav === id ? ' active-link' : ''}`}>
                                    <i className={`uil ${icon} nav__icon`} aria-hidden="true"></i>
                                    {label}
                                </a>
                            </li>
                        ))}
                    </ul>
                </div>
                <button type="button" className="nav__toggle" aria-label={showMenu ? 'Close navigation menu' : 'Open navigation menu'} aria-expanded={showMenu} aria-controls="site-navigation" onClick={() => setShowMenu(!showMenu)}>
                    <i className={`uil ${showMenu ? 'uil-times' : 'uil-apps'}`} aria-hidden="true"></i>
                </button>
            </nav>
        </header>
    )
}
